(7245263, 1124197, 96751, '<td valign="top">Nice lines :)</td>', 'Nice lines :)', '2014-07-29 12:01:04.000000', NULL, 1),
(7245264, 1124365, 96751, '<td valign="top">Nice tableau, although it needs a bit more separation from the bg. The "special" sort of disappears on the right</td>', 'Nice tableau, although it needs a bit more separation from the bg. The "special" sort of disappears on the right', '2014-07-29 12:01:46.000000', NULL, 1),
(7245265, 1124117, 96751, '<td valign="top">Lovely, soft colors, although there are a number of technical issues for me.  The bg cloth is all wrinkled, the cup and saucer are tilted to the left, and it looks like you were going for some vignetting with your lighting - however, the result is that the bottom right of the image is too dark, while the spill illuminates most of the (uninteresting) bg.</td>', 'Lovely, soft colors, although there are a number of technical issues for me.  The bg cloth is all wrinkled, the cup and saucer are tilted to the left, and it looks like you were going for some vignetting with your lighting - however, the result is that the bottom right of the image is too dark, while the spill illuminates most of the (uninteresting) bg.', '2014-07-29 12:04:06.000000', NULL, 1),
(7245266, 1124352, 96751, '<td valign="top">Wonderful! Such lovely cups.  I might have had less light on the bg.</td>', 'Wonderful! Such lovely cups.  I might have had less light on the bg.', '2014-07-29 12:04:34.000000', NULL, 1),
(7245267, 1124194, 96751, '<td valign="top">Haha!</td>', 'Haha!', '2014-07-29 12:04:54.000000', NULL, 1),
(7245269, 1124373, 96751, '<td valign="top">Great title!!  Just wish the elements were slightly closer together. I find the distance in the center throws off the balance</td>', 'Great title!!  Just wish the elements were slightly closer together. I find the distance in the center throws off the balance', '2014-07-29 12:06:11.000000', NULL, 1),
(7245270, 1123644, 96751, '<td valign="top">Awwww</td>', 'Awwww', '2014-07-29 12:06:21.000000', NULL, 1),
