(7245277, 1124423, 96751, '<td valign="top">Ah, Tate. You are charming :)</td>', 'Ah, Tate. You are charming :)', '2014-07-29 12:09:16.000000', NULL, 1),
(7245278, 1124367, 172889, '<td valign="top">Nicely done original bokeh</td>', 'Nicely done original bokeh', '2014-07-29 12:11:14.000000', NULL, 1),
(7245285, 1124362, 172889, '<td valign="top">It looks like he''s holding the cup only to strengthen his position in an argument where he won''t even take a sip of his cup. Great</td>', 'It looks like he''s holding the cup only to strengthen his position in an argument where he won''t even take a sip of his cup. Great', '2014-07-29 12:17:48.000000', NULL, 1),
(7245286, 1124268, 96751, '<td valign="top">Great concept, although God is in the details for this sort of setup :)<br/> <br/>First, the tilt... I''m also not sure what the cloth thing is, or why it''s there, but it''s all scrunched up, which is distracting and makes no sense. Also, eliminating it would have also increased the area of the wonderful reflection.<br/> <br/>Lightingwise, it is good, but I think this could have been great.  A bit more distance from the background would not have lit it up so much. Also, I think I see two light sources - rather than have them evenly lit, I might have tried for the key on camera right to be at least 2/3 stronger than the fill on the left. The lighting could also have been improved in post, adding a bit of a vignette, and some more brightness to the subject. There''s an overall dullness to the lighting to my eye.</td>', 'Great concept, although God is in the details for this sort of setup :) First, the tilt... I''m also not sure what the cloth thing is, or why it''s there, but it''s all scrunched up, which is distracting and makes no sense. Also, eliminating it would have also increased the area of the wonderful reflection. Lightingwise, it is good, but I think this could have been great.  A bit more distance from the background would not have lit it up so much. Also, I think I see two light sources - rather than have them evenly lit, I might have tried for the key on camera right to be at least 2/3 stronger than the fill on the left. The lighting could also have been improved in post, adding a bit of a vignette, and some more brightness to the subject. There''s an overall dullness to the lighting to my eye.', '2014-07-29 12:18:13.000000', NULL, 1),
(7245288, 1124423, 172889, '<td valign="top">Great pov and image ratio</td>', 'Great pov and image ratio', '2014-07-29 12:19:51.000000', NULL, 1),
(7245289, 1124441, 172889, '<td valign="top">Oh no, the headache</td>', 'Oh no, the headache', '2014-07-29 12:23:17.000000', NULL, 1),
(7245291, 1123854, 96751, '<td valign="top">Lovely emotion!</td>', 'Lovely emotion!', '2014-07-29 12:27:50.000000', NULL, 1),
